package com.example.starter.batch;

/**
 * 检验结论：PASS 通过；FAIL 不通过（任一 FAIL 立即使批次进入 REJECTED）。
 */
public enum TestOutcome {
    PASS,
    FAIL
}

package com.example.starter.batch;

/**
 * 放行批准角色：QUALITY 质量、OPERATIONS 运营；两步批准必须由两种不同角色完成。
 */
public enum ApprovalRole {
    QUALITY,
    OPERATIONS
}

package com.example.starter.batch;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带可区分的 HTTP 状态（400 参数非法、404 不存在、409 状态/键冲突、422 前置条件未满足）。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ARGUMENT", message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, "CONFLICT", message);
    }

    public static ApiException unprocessable(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "PRECONDITION_FAILED", message);
    }
}

package com.example.starter.batch;

/**
 * 统一错误响应体：code 机器可区分，message 面向人。
 */
public record ErrorResponse(String code, String message) {
}

